251		for (const line of lines) {
252			const titleMatch = line.match(/^#\s+Animation Storyboard:\s*(.+)$/);
253			if (titleMatch) continue;
254			const sceneMatch = line.match(/^##\s+Scene\s+(\d+):\s*(.+?)\s*\((\d+(?:\.\d+)?(?:\s*-\s*\d+(?:\.\d+)?)?s)\)\s*$/);
255			if (sceneMatch) {
256				if (current.title) scenes.push(current as StoryboardScene);
257				current = {
258					number: Number(sceneMatch[1]),
259					title: sceneMatch[2].trim(),
260					duration: sceneMatch[3].trim(),
261				};
262				continue;
263			}
264			const visualMatch = line.match(/^-\s*\*\*Visual\*\*:\s*(.+)$/);
265			if (visualMatch) current.visual = visualMatch[1].trim();
266			const audioMatch = line.match(/^-\s*\*\*(?:Audio|Narration)\*\*:\s*(.+)$/);
267			if (audioMatch) current.audio = audioMatch[1].trim();
268			const transMatch = line.match(/^-\s*\*\*Transition\*\*:\s*(.+)$/);
269			if (transMatch) current.transition = transMatch[1].trim();
270			const durMatch = line.match(/^-\s*\*\*Duration\*\*:\s*(\d+)s\s*$/);
271			if (durMatch) current.duration = `${durMatch[1]}s`;
272			const highlightMatch = line.match(/^-\s*\*\*(?:Highlight|Overlay|Step-through)\*\*:\s*(.+)$/);
273			if (highlightMatch) current.highlight = highlightMatch[1].trim();
274		}
275		if (current.title) scenes.push(current as StoryboardScene);
276		return scenes;
